-- R6 immutable proposal versions and approved-only comparison command.
CREATE OR REPLACE FUNCTION public.mmhr_record_proposal(payload jsonb, correlation_id uuid, idempotency_key uuid)
RETURNS jsonb LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path = '' AS $$
DECLARE context record; receipt jsonb; proposal public.proposal_versions%ROWTYPE; comparison public.proposal_comparisons%ROWTYPE; v_action text; v_org uuid; v_actor uuid; v_id uuid; v_deal uuid; v_vendor uuid; v_status text; v_ids jsonb; v_approvers jsonb;
BEGIN
 IF jsonb_typeof(payload)<>'object' OR coalesce(payload->>'action','') NOT IN ('create','review','compare') OR correlation_id IS NULL OR idempotency_key IS NULL OR coalesce(payload->>'organizationId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'actorIdentityId','') !~ '^[0-9a-fA-F-]{36}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid proposal input'; END IF;
 v_action:=payload->>'action'; v_org:=(payload->>'organizationId')::uuid; v_actor:=(payload->>'actorIdentityId')::uuid; SELECT * INTO context FROM mmhr_private.r1_start_security_command('workspace.access',v_org,'Record proposal',correlation_id,idempotency_key); IF v_actor<>context.actor_identity_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Security command denied'; END IF;
 receipt:=mmhr_private.r1_checked_receipt(context.actor_identity_id,'r6.proposal',idempotency_key,payload); IF receipt IS NOT NULL THEN RETURN jsonb_build_object('entityId',receipt->>'entity_id','organizationId',v_org,'outcomeCode','replayed','correlationId',correlation_id); END IF;
 IF v_action='create' THEN
   IF coalesce(payload->>'proposalId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'dealId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'vendorOrganizationId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'createdByIdentityId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce((payload->>'versionNumber')::integer,0)<1 OR jsonb_typeof(payload->'sourceReferences')<>'array' OR jsonb_array_length(payload->'sourceReferences')<1 OR jsonb_array_length(payload->'sourceReferences')>50 OR jsonb_typeof(payload->'pricing')<>'object' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid proposal create'; END IF;
   v_id:=(payload->>'proposalId')::uuid; v_deal:=(payload->>'dealId')::uuid; v_vendor:=(payload->>'vendorOrganizationId')::uuid; IF NOT EXISTS(SELECT 1 FROM public.deals d WHERE d.id=v_deal AND d.organization_id=v_org AND d.vendor_organization_id=v_vendor) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Proposal deal scope denied'; END IF;
   INSERT INTO public.proposal_versions(id,organization_id,deal_id,vendor_organization_id,version_number,status,received_at,source_references,pricing,created_by_identity_id) VALUES(v_id,v_org,v_deal,v_vendor,(payload->>'versionNumber')::integer,'received',(payload->>'receivedAt')::timestamptz,payload->'sourceReferences',payload->'pricing',(payload->>'createdByIdentityId')::uuid) RETURNING * INTO proposal;
 ELSE
   IF v_action='review' THEN v_id:=(payload->>'proposalId')::uuid; v_status:=payload->>'status'; IF v_id IS NULL OR v_status NOT IN ('under_review','revision_requested','approved_for_comparison','superseded','withdrawn') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid proposal review'; END IF; SELECT * INTO proposal FROM public.proposal_versions WHERE id=v_id AND organization_id=v_org FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Proposal association denied'; END IF; UPDATE public.proposal_versions SET status=v_status WHERE id=v_id AND organization_id=v_org RETURNING * INTO proposal;
   ELSE
     IF coalesce(payload->>'comparisonId','') !~ '^[0-9a-fA-F-]{36}$' OR coalesce(payload->>'dealId','') !~ '^[0-9a-fA-F-]{36}$' OR jsonb_typeof(payload->'proposalVersionIds')<>'array' OR jsonb_array_length(payload->'proposalVersionIds') NOT BETWEEN 2 AND 50 OR jsonb_typeof(payload->'approvedByIdentityIds')<>'array' OR jsonb_array_length(payload->'approvedByIdentityIds') NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='Invalid proposal comparison'; END IF; v_id:=(payload->>'comparisonId')::uuid; v_deal:=(payload->>'dealId')::uuid; v_ids:=payload->'proposalVersionIds'; v_approvers:=payload->'approvedByIdentityIds'; IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(v_ids) x WHERE NOT EXISTS(SELECT 1 FROM public.proposal_versions p WHERE p.id=x.value::uuid AND p.organization_id=v_org AND p.deal_id=v_deal AND p.status='approved_for_comparison')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Proposal comparison approval denied'; END IF; INSERT INTO public.proposal_comparisons(id,organization_id,deal_id,proposal_version_ids,approved_by_identity_ids,approved_at,created_by_identity_id,correlation_id) VALUES(v_id,v_org,v_deal,v_ids,v_approvers,(payload->>'approvedAt')::timestamptz,v_actor,correlation_id) RETURNING * INTO comparison;
   END IF;
 END IF;
 PERFORM mmhr_private.r1_finish_security_command(context.actor_identity_id,'r6.proposal','proposal.'||v_action,CASE WHEN v_action='compare' THEN 'proposal_comparison' ELSE 'proposal_version' END,CASE WHEN v_action='compare' THEN comparison.id ELSE proposal.id END,v_org,'Record proposal',correlation_id,idempotency_key,payload,jsonb_build_object('status','completed'),jsonb_build_object('status','completed'),context.authorization_time);
 RETURN jsonb_build_object('entityId',CASE WHEN v_action='compare' THEN comparison.id ELSE proposal.id END,'organizationId',v_org,'status',coalesce(proposal.status,'approved'),'outcomeCode','recorded','correlationId',correlation_id);
END; $$;
REVOKE ALL ON FUNCTION public.mmhr_record_proposal(jsonb,uuid,uuid) FROM PUBLIC,anon,authenticated,service_role,mmhr_worker; GRANT EXECUTE ON FUNCTION public.mmhr_record_proposal(jsonb,uuid,uuid) TO authenticated;
